            dag.key(ancestor).is_some_and(|prerequisite| {
                succeeded(prerequisite)
                    || (issued.contains(prerequisite) && is_registry_effect(id) && is_registry_effect(prerequisite))
            })
        })
    })
    .map(|(_, id)| id.clone())
    .collect()
}

