        .apply(operation, event)
        .map(|_| ())
        .map_err(|source| match source {
            ReleaseStateError::EvidenceRejected(source) => GraphError::ReleaseProviderObservation { source },
            source => GraphError::ReleaseExecutionState { source },
        })
}

